#!/usr/bin/env python3
"""CurvTab Dental 2.0 — Visual upgrade installer.

Run from Codespaces repository root:
    python3 curvtab_visual_upgrade.py

Scope: backs up and changes only frontend/src/App.tsx and
frontend/src/pages/AppointmentsPage.tsx; adds design and slideshow files.
Does not touch backend, migrations or PostgreSQL.
"""
from pathlib import Path
from datetime import datetime, timezone
import base64
import re
import shutil
import sys
import zlib

PAYLOAD = {
    'frontend/public/dental-ui/smile-hero.webp': '',
    'frontend/public/dental-ui/tooth-care.svg': '',
    'frontend/public/dental-ui/tooth-fresh.svg': '',
    'frontend/src/CurvTabVisualUpgrade.css': '',
    'frontend/src/components/ClinicDashboardEnhancements.css': '',
    'frontend/src/components/ClinicDashboardEnhancements.tsx': '',
}

root = Path.cwd()
app_path = root / 'frontend/src/App.tsx'
appointments_path = root / 'frontend/src/pages/AppointmentsPage.tsx'
if not app_path.is_file() or not appointments_path.is_file():
    sys.exit('ERROR: Run from /workspaces/CurvTab-Dental-2.0. Frontend files not found.')

newpaths = [root / filename for filename in PAYLOAD]
existing = [p for p in newpaths if p.exists()]
if existing:
    sys.exit('ERROR: Upgrade files already exist. No changes made: ' + ', '.join(str(p) for p in existing))

app = app_path.read_text(encoding='utf-8')
appts = appointments_path.read_text(encoding='utf-8')
if 'ClinicDashboardEnhancements' in app or 'ct-calendar-status-dots' in appts:
    sys.exit('ERROR: A previous visual upgrade appears installed. Not applying twice.')

needle = '<main className="main-content">'
if app.count(needle) != 1:
    sys.exit('ERROR: App.tsx main-content anchor missing/duplicated. No changes made.')
app = "import ClinicDashboardEnhancements from './components/ClinicDashboardEnhancements'\nimport './CurvTabVisualUpgrade.css'\n" + app
app = app.replace(needle, needle + '''
          {/* Visual upgrade: slideshow and real-data appointment analytics. */}
          {section === 'Dashboard' && (
            <ClinicDashboardEnhancements
              role={role}
              onPrimaryAction={() => {
                if (role === 'SuperAdmin') navigate('Dental Practices')
                else openAppointmentTab('Scheduling')
              }}
            />
          )}
''', 1)

# Keep Profile last while tolerating variations in the existing sidebar markup.
# Previous installer only matched <nav className="side-nav"> exactly.
# In modified versions of App.tsx, the nav may use a different class or props.
nav_match = None
for match in re.finditer(r'<nav\b[^>]*>', app, flags=re.S):
    closing = app.find('</nav>', match.end())
    if closing == -1:
        continue
    candidate = app[match.end():closing]
    if 'nav-item' in candidate or 'My Profile' in candidate or 'key={item.name}' in candidate:
        nav_match = (match.start(), match.end(), closing)
        break

if nav_match is None:
    sys.exit('ERROR: Could not locate the sidebar navigation. No changes made.')

navstart, navopen_end, navend = nav_match
nav_open = app[navstart:navopen_end]
nav_body = app[navopen_end:navend]

# CSS order works only on elements participating in a flex layout.
# Existing sidebar is vertical; explicitly retain that arrangement.
if 'style=' not in nav_open:
    nav_open = nav_open[:-1] + " style={{ display: 'flex', flexDirection: 'column' }}>"

# Nav items produced by .map(): ensure that My Profile sorts after any
# additional static Dentist/Receptionist module buttons.
if 'key={item.name}' in nav_body and 'data-profile-nav=' not in nav_body:
    nav_body = nav_body.replace(
        'key={item.name}',
        "key={item.name}\n                style={{ order: item.name === 'My Profile' ? 999 : 0 }}\n                data-profile-nav={item.name === 'My Profile' ? 'true' : undefined}",
        1,
    )

# Some versions render My Profile as a separate button instead of a mapped item.
profile_button = re.search(
    r'<button\b(?:(?!</button>).)*?onClick=\{\(\) => navigate\([\'"]My Profile[\'"]\)\}(?:(?!</button>).)*?>',
    nav_body,
    flags=re.S,
)
if profile_button:
    btn = profile_button.group()
    if 'style=' not in btn:
        nav_body = nav_body[:profile_button.start()] + btn[:-1] + ' style={{ order: 999 }}>' + nav_body[profile_button.end():]

app = app[:navstart] + nav_open + nav_body + app[navend:]

# Convert existing single-color booking dots into multi-status dots.
pattern = re.compile(r"\{booked\s*&&\s*<span\s+className=['\"]booking-dot['\"]\s*/>\}")
match = pattern.search(appts)
if not match:
    sys.exit('ERROR: AppointmentsPage.tsx booking-dot anchor changed. No changes made.')
colored = '''{booked && (
                      <span className="ct-calendar-status-dots" aria-hidden="true">
                        {Array.from(new Set(appointments
                          .filter((appointment) => dateKey(new Date(appointment.startUtc)) === key)
                          .map((appointment) => appointment.status)
                        )).slice(0, 4).map((status) => (
                          <span
                            key={status}
                            className={`ct-status-dot ct-status-${status.toLowerCase()}`}
                            title={status}
                          />
                        ))}
                      </span>
                    )}'''
appts = appts[:match.start()] + colored + appts[match.end():]

appts = appts.replace(
    '<small>{item.status}</small>',
    '<small className={`ct-status ct-status-${item.status.toLowerCase()}`}>{item.status}</small>', 1,
)
appts = appts.replace(
    '<small>Status: {item.status}</small>',
    '<small className={`ct-status ct-status-${item.status.toLowerCase()}`}>Status: {item.status}</small>', 1,
)
if 'A dot indicates saved bookings on that date.' in appts:
    appts = appts.replace('A dot indicates saved bookings on that date.',
                          'Colored dots show saved appointment statuses for each day.', 1)

# Label the status colors beneath the existing appointment calendar.
note = '<p className="panel-note">\n              Colored dots show saved appointment statuses for each day.'
if note in appts:
    legend = (
        '<div className="ct-calendar-legend" aria-label="Appointment calendar color legend">\n'
        '  <span><i className="ct-legend-scheduled"/>Scheduled</span>\n'
        '  <span><i className="ct-legend-progress"/>In progress</span>\n'
        '  <span><i className="ct-legend-checkout"/>Checkout</span>\n'
        '  <span><i className="ct-legend-done"/>Checked out</span>\n'
        '</div>\n            '
    )
    appts = appts.replace(note, legend + note, 1)

if 'onPrimaryAction' not in app or 'ct-calendar-status-dots' not in appts:
    sys.exit('ERROR: Changes could not be verified. No files changed.')

backup = root / '.curvtab-ui-backups' / datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f')
backup.mkdir(parents=True, exist_ok=False)
shutil.copy2(app_path, backup / 'App.tsx')
shutil.copy2(appointments_path, backup / 'AppointmentsPage.tsx')
try:
    for filename, encoded in PAYLOAD.items():
        target = root / filename
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(zlib.decompress(base64.b64decode(encoded)))
    app_path.write_text(app, encoding='utf-8')
    appointments_path.write_text(appts, encoding='utf-8')
except Exception as exc:
    shutil.copy2(backup / 'App.tsx', app_path)
    shutil.copy2(backup / 'AppointmentsPage.tsx', appointments_path)
    for target in newpaths:
        target.unlink(missing_ok=True)
    sys.exit(f'ERROR: Installation failed; source restored: {exc}')

print('SUCCESS: CurvTab Dental visual upgrade installed.')
print('Backup:', backup)
print('Adds interactive slideshow, real-data charts, hover effects, dropdown arrows,')
print('responsive cards, colored appointment statuses, and Profile last.')
print('No migrations, backend or database changes.')
print('NEXT: cd frontend && npm run build && npm run lint')
